INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خذل:ibn_durayd_jamharat_lugha', 'خذل', '9729e668ce3670420839c3f264', 'خذلت الرجل أخذله خذلا وخذلانا إِذا تركت معونته', 'I stopped helping the man', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_bba2a268773c7a27', '540', NULL, 'blk_jam_639ad0fbd25261fe', 0, NULL, 'Marker: «إذا». Reading: leaving without help.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خذل:jawhari_sihah', 'خذل', '9729e668ce3670420839c3f264', 'خِذْلاناً، إذا ترك عونَه ونُصْرَتَهُ', 'he stopped helping and backing him', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_ec33141f8e7cf79b', '3335', 4, 'blk_sih_3d293d75b1cc1204', 0, NULL, 'Marker: «إذا». Reading: leaving without help.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خذل:raghib_mufradat', 'خذل', '9729e668ce3670420839c3f264', 'والخِذْلَان: ترك من يظنّ به أن ينصر نصرته', 'failing to help when help was expected', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_0d07dd15485c7dd7', '277', 1, 'blk_mfr_6c906fcb88fb8397', 0, NULL, 'Marker: opening definition. Reading: letting down.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خذل:ibn_manzur_lisan_arab', 'خذل', '9729e668ce3670420839c3f264', 'الخاذِلُ: ضِدُّ النَّاصِرِ. خَذَلَه وخَذَلَ عَنْهُ يَخْذُلُهُ خَذْلًا وخِذْلاناً: تَرَكَ نُصْرته وعَوْنه', 'the opposite of a helper; left him unhelped', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_7154e7cdd105570e', '5382', 11, 'blk_lsn_690a6811af6f627a', 0, NULL, 'Marker: head gloss. Reading: leaving without help.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خذل:fayyumi_misbah_munir', 'خذل', '9729e668ce3670420839c3f264', 'خَذَلْتُهُ وَخَذَلْتُ عَنْهُ مِنْ بَابِ قَتَلَ وَالِاسْمُ الْخِذْلَانُ إذَا تَرَكْتَ نُصْرَتَهُ', 'when you stop backing him', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_ce4494b67c87908c', '818', NULL, 'blk_msb_9718119a959e61ae', 0, NULL, 'Marker: head gloss («إذا»). Reading: leaving without help.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خذل:qamus_muhit', 'خذل', '9729e668ce3670420839c3f264', 'خَذَلَه، وعنهُ خَذْلاً وخِذْلاناً، بالكسر: تَرَكَ نُصْرَتَهُ', 'he left him without help', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_06a16f632b09fa42', NULL, NULL, 'blk_qms_f7879091e14aea8b', 0, NULL, 'Marker: Qāmūs gloss. Reading: leaving without help.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خذل:zabidi_taj_arus', 'خذل', '9729e668ce3670420839c3f264', 'خَذَلَهُ، خَذَل عَنهُ خَذْلاً بِالْفَتْح وخِذْلاناً، بِالْكَسْرِ: تَرَك نُصْرَتَه', 'he left him without help', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_57ce737af6f74ddc', '399', 28, 'blk_taj_b56cd00806f8e1c4', 0, NULL, 'Marker: Qāmūs gloss. Reading: leaving without help.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خذل:lane_lexicon', 'خذل', '9729e668ce3670420839c3f264', 'He abstained from, or neglected, aiding him, or assisting him', 'he held back from helping him', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_9ed75076211d8603', '713', NULL, 'blk_lane_382e6a3b2bd5ea41', 0, NULL, 'Marker: first sense A1. Reading: withholding help.', 'high', 'active');
