INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خرب:ibn_durayd_jamharat_lugha', 'خرب', '1d7da114e90fe016028930b8e7', 'والخربة: خرق فِي الورك فِي الْعظم يلْبسهُ اللَّحْم وَالْجَلد ينفذ إِلَى الْجوف', 'a hole in the hip bone', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_d2e44a386d7f289c', '251', NULL, 'blk_jam_e9a0bf573975453d', 0, NULL, 'Marker: first gloss of the root''s sense. Reading: hole. Differs from the main reading (ruin, the opposite of building).', 'medium', 'active');
