INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خشع:zabidi_taj_arus', 'خشع', '90d5c9e88377fc21d1e7c60e53', 'الخُشُوعُ: الخُضُوعُ: كالاخِتْشاعِ', 'lowering oneself, submission', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_6bacc7f78302a2fb', '506', 20, 'blk_taj_7fdc491a219590dc', 0, NULL, 'Marker: Qāmūs gloss. Reading: submission.', 'high', 'active');
