INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خصف:khalil_kitab_ayn', 'خصف', '8b768a3d536e62b74cc2aeb0d0', 'الخَصَفُ نياب غلاظ جدا', 'very thick cloth', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_be16c83a872293c4', '1296', NULL, 'blk_kay_87ca21371be3d1db', 0, NULL, 'Marker: head gloss. Reading: thick cloth. Differs from the main reading (joining layers together).', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خصف:ibn_durayd_jamharat_lugha', 'خصف', '8b768a3d536e62b74cc2aeb0d0', 'خصفت النَّعْل أخصفها خصفا فَهِيَ مخصوفة وَأَنا خاصف إِذا أطبقت عَلَيْهَا طبقًا', 'I laid a layer over the sandal sole', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_bba2a268773c7a27', '540', NULL, 'blk_jam_c0451fedd2f755e2', 0, NULL, 'Marker: «إذا». Reading: layering a sole. Primary: joining layers together — 9 of 10 books (Ibn Durayd blk_jam_c0451fedd2f755e2; al-Jawharī blk_sih_eda3ef6838bd8ded; Ibn Fāris blk_mqy_557df5229fcfc7b7; al-Rāghib blk_mfr_1cee30149d8e19d0; Lisān blk_lsn_be92a59f15ab9aa2; al-Miṣbāḥ blk_msb_c019cddc060a469e; al-Qāmūs blk_qms_7dd7ed339e7b585c; Tāj blk_taj_7dd86311b4bb6ce4; Lane blk_lane_5e3a6f51de19052f). Other readings: thick cloth or mat: al-Khalīl.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خصف:jawhari_sihah', 'خصف', '8b768a3d536e62b74cc2aeb0d0', 'الخَصْفُ: النعلُ ذات الطِراق', 'a sandal made of stacked layers', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_4f1de1b710228ac6', '2670', 4, 'blk_sih_eda3ef6838bd8ded', 0, NULL, 'Marker: head gloss. Reading: layered sandal.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خصف:raghib_mufradat', 'خصف', '8b768a3d536e62b74cc2aeb0d0', 'أي: يجعلان عليهما خَصَفَةً، وهي أوراق', 'they put leaves over themselves', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_203e53d106f6699d', '284', 1, 'blk_mfr_1cee30149d8e19d0', 0, NULL, 'Marker: «أي». Reading: covering with leaves.', 'medium', 'active');
