INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خصف:fayyumi_misbah_munir', 'خصف', '8b768a3d536e62b74cc2aeb0d0', 'خَصَفَ الرَّجُلُ نَعْلَهُ خَصْفًا مِنْ بَابِ ضَرَبَ فَهُوَ خَصَّافٌ وَهُوَ فِيهِ كَرَقْعِ الثَّوْبِ', 'he patched his sandal, like patching a garment', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_bcb3791a8e740d32', '859', NULL, 'blk_msb_c019cddc060a469e', 0, NULL, 'Marker: head gloss. Reading: patching a sole.', 'high', 'active');
