INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خصم:raghib_mufradat', 'خصم', '6f1205db3575af7586c9b3c44f', 'الخَصْمُ مصدر خَصَمْتُهُ، أي: نازعته خَصْماً', 'I quarrelled with him', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_420d20544aa14233', '284', 1, 'blk_mfr_82d337ccccc6f14b', 0, NULL, 'Marker: «أي». Reading: quarrelling.', 'high', 'active');
