INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خضد:khalil_kitab_ayn', 'خضد', 'd85fa3552ee4fc80853d5aa9c9', 'الخَضْدُ: نزع الشوك عن الشجر', 'pulling thorns off trees', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_bac84c1e10aa506f', '1283', NULL, 'blk_kay_90ec2fd76837d1a0', 0, NULL, 'Marker: head gloss. Reading: removing thorns. Differs from the main reading (bending or breaking without snapping off).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خضد:ibn_durayd_jamharat_lugha', 'خضد', 'd85fa3552ee4fc80853d5aa9c9', 'خضدت الْعود أخضده خضدا إِذا ثنيته وَلم تكسره', 'I bent the stick without breaking it', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_bba2a268773c7a27', '540', NULL, 'blk_jam_5b329366ef631d83', 0, NULL, 'Marker: «إذا». Reading: bending without breaking. Primary: bending or breaking without snapping off — 7 of 9 books (Ibn Durayd blk_jam_5b329366ef631d83; al-Jawharī blk_sih_3b93822bc6b71f63; Ibn Fāris blk_mqy_c4733047ec209330; Lisān blk_lsn_85c42fa063c07f85; al-Qāmūs blk_qms_f625db52e114be7f; Tāj blk_taj_e3f1f237e1edcd97; Lane blk_lane_a724aa1688992b35). Other readings: cutting off thorns: al-Khalīl, al-Rāghib.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خضد:jawhari_sihah', 'خضد', 'd85fa3552ee4fc80853d5aa9c9', 'خَضَدْتُ العودَ فانْخَضَدّ، أي ثَنَيْتُهُ فانْثَنى من غير كَسْرٍ', 'I bent the stick and it bent, unbroken', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_24f56a2601e4e94d', '921', 2, 'blk_sih_3b93822bc6b71f63', 0, NULL, 'Marker: head gloss. Reading: bending without breaking.', 'high', 'active');
