INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خفف:ibn_manzur_lisan_arab', 'خفف', '413a23f23053d6114d5872c2de', 'الخَفَّةُ والخِفّةُ: ضِدُّ الثِّقَلِ والرُّجُوحِ، يَكُونُ فِي الْجِسْمِ والعقلِ والعملِ', 'the opposite of heaviness, in body, mind and work', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_1521ace5fc5613a2', '4386', 9, 'blk_lsn_f26cbdd9816b511b', 0, NULL, 'Marker: head gloss. Reading: lightness.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خفف:fayyumi_misbah_munir', 'خفف', '413a23f23053d6114d5872c2de', 'خَفَّ الشَّيْءُ خَفًّا مِنْ بَابِ ضَرَبَ وَخِفَّةً ضِدُّ ثَقُلَ', 'the thing was light, not heavy', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_706d0b0cb5b6466a', '880', NULL, 'blk_msb_6f4b56c0e5e84496', 0, NULL, 'Marker: head gloss. Reading: lightness.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خفف:qamus_muhit', 'خفف', '413a23f23053d6114d5872c2de', 'الخُفُّ، بالضم: مَجْمَعُ فِرْسِنِ البَعيرِ', 'the camel''s foot pad', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_b5ebdd1af0df7945', NULL, NULL, 'blk_qms_0ea46946e7f3f6f8', 0, NULL, 'Marker: Qāmūs gloss. Reading: camel''s foot pad. Differs from the main reading (lightness).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خفف:zabidi_taj_arus', 'خفف', '413a23f23053d6114d5872c2de', 'الْخُفٌّ، بِالضَّمِّ: مَجْمَعُ فِرْسِنِ الْبَعِير، والنَّاقَةِ', 'the foot pad of a camel', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_526d030c2432d923', '232', 23, 'blk_taj_01c2f777ddc310ca', 0, NULL, 'Marker: Qāmūs gloss. Reading: camel''s foot pad. Differs from the main reading (lightness).', 'high', 'active');
