INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خفي:zabidi_taj_arus', 'خفي', '0fd7e2330071eeb9cf02ef9e31', 'وخُفِيّاً) ، كعُتِيَ: (أَظْهَرَهُ) ؛ وَهُوَ مِن الأَضْدَادِ', 'he showed it; a word with opposite meanings', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_8932f303fe403965', '562', 37, 'blk_taj_e78c1a6eae334a89', 0, NULL, 'Marker: Qāmūs gloss. Reading: showing. Differs from the main reading (hiding).', 'medium', 'active');
