INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خلص:khalil_kitab_ayn', 'خلص', '8300320eef02592cb41a0e12aa', 'خَلصَ الشيء خُلوصاً، إذا كان قد نشب، ثم نجا وسلم', 'it was caught, then got free and safe', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_bd945952f250814b', '1294', NULL, 'blk_kay_4615d4db99832c0f', 0, NULL, 'Marker: «إذا». Reading: getting free. Differs from the main reading (being pure, clearing of mixture).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خلص:ibn_durayd_jamharat_lugha', 'خلص', '8300320eef02592cb41a0e12aa', 'وخلص الشَّيْء يخلص خلوصا وخلاصا وخلصته أَنا تخليصا إِذا صفيته من كدر أَو درن', 'I cleaned it of murk or dirt', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_bba2a268773c7a27', '540', NULL, 'blk_jam_4d553d2ad15101b1', 0, NULL, 'Marker: «إذا». Reading: making pure. Primary: being pure, clearing of mixture — 8 of 10 books (Ibn Durayd blk_jam_4d553d2ad15101b1; al-Jawharī blk_sih_f38858c24509d583; Ibn Fāris blk_mqy_69346aba7b602ea7; al-Rāghib blk_mfr_f7f4350995cc5852; al-Qāmūs blk_qms_2c3ee7204e59ed8f; Tāj blk_taj_17ae4f90c413d141; Lane blk_lane_29cd30a1b62a11fc; al-Miṣbāḥ blk_msb_ecaf187d7c038e45). Other readings: getting free, escaping: al-Khalīl, Lisān, al-Miṣbāḥ.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خلص:jawhari_sihah', 'خلص', '8300320eef02592cb41a0e12aa', 'خلص الشئ بالفتح يخلص خُلوصاً، أي صار خالِصاً', 'the thing became pure', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_e2678837444e7c38', '2055', 3, 'blk_sih_f38858c24509d583', 0, NULL, 'Marker: head gloss. Reading: becoming pure.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خلص:raghib_mufradat', 'خلص', '8300320eef02592cb41a0e12aa', 'الخالص كالصافي إلّا أنّ الخالص هو ما زال عنه شوبه بعد أن كان فيه', 'pure: what has lost its mixture', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_8e0d8190f6d2d971', '292', 1, 'blk_mfr_f7f4350995cc5852', 0, NULL, 'Marker: head gloss. Reading: pure after cleaning.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خلص:ibn_manzur_lisan_arab', 'خلص', '8300320eef02592cb41a0e12aa', 'خَلَص الشَّيْءُ، بِالْفَتْحِ، يَخْلُص خُلُوصاً وخَلاصاً إِذا كَانَ قَدْ نَشِبَ ثُمَّ نَجا وسَلِم', 'it was caught, then got free and safe', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_7c161e844ee11cc0', '3409', 7, 'blk_lsn_928903968d21be08', 0, NULL, 'Marker: head gloss. Reading: getting free. Differs from the main reading (being pure, clearing of mixture).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خلص:fayyumi_misbah_munir', 'خلص', '8300320eef02592cb41a0e12aa', 'خَلَصَ الشَّيْءُ مِنْ التَّلَفِ خُلُوصًا مِنْ بَابِ قَعَدَ وَخَلَاصًا وَمَخْلَصًا سَلِمَ وَنَجَا', 'it escaped harm and was safe', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_061ffe6deef410c1', '889', NULL, 'blk_msb_ecaf187d7c038e45', 0, NULL, 'Marker: head gloss. Reading: getting free. Also gives: being pure, clearing of mixture (blk_msb_ecaf187d7c038e45).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خلص:qamus_muhit', 'خلص', '8300320eef02592cb41a0e12aa', 'خَلَصَ خلُوصاً وخالِصةً: صارَ خالِصاً', 'it became pure', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_68095121db640555', NULL, NULL, 'blk_qms_2c3ee7204e59ed8f', 0, NULL, 'Marker: Qāmūs gloss. Reading: becoming pure.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خلص:zabidi_taj_arus', 'خلص', '8300320eef02592cb41a0e12aa', 'وقيلَ الخَالِصَةُ والخَلَاصُ: اسْمَانِ: صَارَ خالِصاً', 'it became pure', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_81c6ad61b95f7967', '558', 17, 'blk_taj_17ae4f90c413d141', 0, NULL, 'Marker: Qāmūs gloss. Reading: becoming pure.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خلص:lane_lexicon', 'خلص', '8300320eef02592cb41a0e12aa', 'It (a thing, Ṣ, TA) was, or became, خَالِص, (Ṣ, A, Ḳ,) which signifies [here] clear, pure, sheer, free from admixture', 'it became clear and pure, unmixed', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_4047ed297e1f079d', '784', NULL, 'blk_lane_29cd30a1b62a11fc', 0, NULL, 'Marker: first sense A1. Reading: being pure.', 'high', 'active');
