INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خلط:ibn_durayd_jamharat_lugha', 'خلط', 'a0330ab859a0d63a6f0b9ff751', 'والخلط: خلطك الشَّيْء بعضه بِبَعْض', 'mixing a thing''s parts together', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_bba2a268773c7a27', '540', NULL, 'blk_jam_05b363b6d65e4549', 0, NULL, 'Marker: head gloss. Reading: mixing. Primary: mixing — 10 of 10 books (al-Khalīl blk_kay_6540b6d4c61343bd; Ibn Durayd blk_jam_05b363b6d65e4549; al-Jawharī blk_sih_61574d6da21e3dd1; Ibn Fāris blk_mqy_09a29f1b952c08de; al-Rāghib blk_mfr_8ec893b5c8643c7a; Lisān blk_lsn_72d2e4c48de2b82c; al-Miṣbāḥ blk_msb_f29e0c6776f5c954; al-Qāmūs blk_qms_2f7a0256a72564a6; Tāj blk_taj_3b013f20a2995a67; Lane blk_lane_4b71771d83aa305b).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خلط:jawhari_sihah', 'خلط', 'a0330ab859a0d63a6f0b9ff751', 'خلطت الشئ بغيره خلطا', 'I mixed the thing with something else', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_85d2509cfe82c7bc', '2229', 3, 'blk_sih_61574d6da21e3dd1', 0, NULL, 'Marker: head gloss. Reading: mixing.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خلط:raghib_mufradat', 'خلط', 'a0330ab859a0d63a6f0b9ff751', 'الخَلْطُ: هو الجمع بين أجزاء الشيئين فصاعدا', 'putting together the parts of two or more things', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_23b9c0d97af03ef4', '293', 1, 'blk_mfr_8ec893b5c8643c7a', 0, NULL, 'Marker: head gloss. Reading: mixing.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خلط:ibn_manzur_lisan_arab', 'خلط', 'a0330ab859a0d63a6f0b9ff751', 'خَلَطَ الشَّيْءُ بِالشَّيْءِ يَخْلِطُه خَلْطاً وخَلَّطَه فاخْتَلَطَ: مَزَجَه', 'he mixed one thing into another', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_c231f3b008710959', '3674', 7, 'blk_lsn_72d2e4c48de2b82c', 0, NULL, 'Marker: head gloss. Reading: mixing.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خلط:fayyumi_misbah_munir', 'خلط', 'a0330ab859a0d63a6f0b9ff751', 'خَلَطْتُ الشَّيْءَ بِغَيْرِهِ خَلْطًا مِنْ بَابِ ضَرَبَ ضَمَمْتُهُ إلَيْهِ فَاخْتَلَطَ هُوَ', 'I joined it to another and it mixed', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_0d0534d2c2dd617f', '890', NULL, 'blk_msb_f29e0c6776f5c954', 0, NULL, 'Marker: head gloss. Reading: mixing.', 'high', 'active');
