INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:خلط:zabidi_taj_arus', 'خلط', 'a0330ab859a0d63a6f0b9ff751', 'خَلَطَهُ، أَي الشَّيْءَ، بغَيْرِه يَخْلِطُه، بالكَسْرِ، خَلْطاً، وخَلَّطَهُ تَخْليطاً: مَزَجَهُ', 'he mixed the thing with another', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_003ba3c959cd1184', '257', 19, 'blk_taj_3b013f20a2995a67', 0, NULL, 'Marker: Qāmūs gloss. Reading: mixing.', 'high', 'active');
